import { NextRequest, NextResponse } from 'next/server';
import { createClient, createServiceClient } from '@/lib/supabase/server';

// ── DB-backed, expiring shared-link store ────────────────────────────────────
// Previously this lived in an in-process `Map`, which — as the original
// comment here noted — gets wiped on every serverless cold start and isn't
// shared across instances on Vercel. Now it's a real table (see
// supabase/schema.sql: shared_links), so a link generated by one invocation
// is readable by any other, and survives redeploys until it expires.
//
// Uses the service-role client for storage/retrieval: creating a link
// requires an HR/manager session, but the manager reading it via token
// deliberately does not require an active login (see FR-10 / proxy.ts).

const TTL_MS = 24 * 60 * 60 * 1000; // 24 hours
const MAX_RECORDS = 5000;

export async function POST(req: NextRequest) {
  const sessionClient = await createClient();
  const { data: { user } } = await sessionClient.auth.getUser();
  if (!user) {
    return NextResponse.json({ error: 'Not authenticated' }, { status: 401 });
  }

  const { data: employee } = await sessionClient
    .from('employees')
    .select('role')
    .eq('auth_user_id', user.id)
    .maybeSingle();

  if (!employee || !['hr', 'hr_super_admin', 'manager', 'lead'].includes(employee.role)) {
    return NextResponse.json({ error: 'Only authorized staff can generate shared links' }, { status: 403 });
  }

  const body = await req.json().catch(() => null);
  if (!body || !Array.isArray(body.records)) {
    return NextResponse.json({ error: 'records array required' }, { status: 400 });
  }
  if (body.records.length > MAX_RECORDS) {
    return NextResponse.json({ error: `Maximum of ${MAX_RECORDS} records allowed per shared link` }, { status: 413 });
  }

  const supabase = createServiceClient();
  const expiresAt = new Date(Date.now() + TTL_MS).toISOString();
  const { data, error } = await supabase
    .from('shared_links')
    .insert({ data: body.records, expires_at: expiresAt })
    .select('token')
    .single();

  if (error || !data) {
    return NextResponse.json({ error: 'Failed to create shared link' }, { status: 500 });
  }

  return NextResponse.json({ token: data.token, expiresAt });
}

export async function GET(req: NextRequest) {
  const token = req.nextUrl.searchParams.get('token');
  if (!token) {
    return NextResponse.json({ error: 'token required' }, { status: 400 });
  }

  const supabase = createServiceClient();
  const { data } = await supabase
    .from('shared_links')
    .select('data, expires_at')
    .eq('token', token)
    .maybeSingle();

  if (!data || new Date(data.expires_at).getTime() <= Date.now()) {
    return NextResponse.json({ error: 'not found or expired' }, { status: 404 });
  }

  return NextResponse.json({ records: data.data });
}
